const defaults = {display_precision:'Auto',display_unit:'Auto'};
const optionalDescriptions = {
  popup_hash:'Optional link to an existing external popup hash. Omit it to use this card’s automatic details.',
  mode_selector_hash:'Optional external climate mode popup hash. Omit it for the automatic mode sheet.',
  action_color:'Optional action background color; does not change the action’s safety rules.',
  action_label:'Optional visible action label.',action_label_key:'Optional Marao localization key for the action label.',
  card_color:'Optional card background color.',md_card_color:'Optional active card color.',graph_color:'Optional graph line/fill color.',
  power_unit:'Label for the configured power reading; unit conversion uses display_unit.',
};
function publicType(id) {return id==='md_energy_period_card'?'custom:marao-energy-card':id==='md_floor_plan_card'?'custom:marao-floorplan-card':`custom:marao-${id.slice(3).replaceAll('_','-')}`;}
function normalFields(card,definition) {
  const list=[field('name','Name','text','Optional display name; otherwise use the entity’s friendly name.'),field('icon','Icon','icon','Optional icon name such as mdi:lightbulb-outline.')];
  if(card.domains.length)list.unshift(field('entity_id','Entity','entity',`A ${card.domains.join(', ')} entity from your Home Assistant.`,{domains:card.domains}));
  for(const variable of card.variables)list.push({...variable,path:`variables.${variable.key}`,kind:variable.multiple?'json':variable.kind,description:variable.description || optionalDescriptions[variable.key] || `${variable.label} for this card.`,...(defaults[variable.key]?{default:defaults[variable.key]}:{})});
  if(['md_entity_group_card','md_scene_collection_card','md_climate_card','md_media_card','md_camera_card','md_energy_period_card','md_graph_card','md_security_card','md_access_card','md_floor_plan_card'].includes(card.id))list.push(field('popup_view','Custom popup view','text','Optional existing view path used for a Home Assistant managed popup layout. Omit for automatic details.'));
  return [...list,...(definition.fields || [])];
}
const commonStateExamples = entity => [
  example('loading','Loading state','Wait for Home Assistant state before showing controls.',{}, {},{loading:true}),
  example('unknown','Unknown state','The entity exists but has no known state. Controls remain neutral and disabled.',{},{[entity]:'unknown'}),
  example('unavailable','Unavailable','The entity is unavailable. No device action is dispatched.',{},{[entity]:'unavailable'}),
  example('missing','Missing entity','A removed entity produces an explicit neutral missing-state result.',{},{[entity]:null}),
  example('disconnected','Disconnected','Controls refuse actions when Home Assistant is disconnected.',{}, {},{disconnected:true}),
];
export const cards = catalog.cards.filter(card=>!card.hidden).map(card=>{
  const definition=definitions[card.id];
  if(!definition)throw new Error(`Missing public documentation for ${card.id}`);
  const base={type:publicType(card.id),...definition.config};
  const sourceExamples=[example('default','Default','Try the configured card with fictional devices.'),...definition.examples,...(base.entity_id?commonStateExamples(base.entity_id):[])];
  return {id:card.id,slug:card.id.slice(3,-5).replaceAll('_','-'),title:card.label,description:card.description,domains:card.domains,config:base,fields:normalFields(card,definition),notes:definition.notes || [],previewLimitations:definition.previewLimitations || [],scenarios:sourceExamples.map(item=>({...item,config:merge(base,item.config),states:scenarioStates(item.states),dashboard:clone(demoDashboard)}))};
});

