export const internalCards = catalog.cards.filter(card=>card.hidden).map(card=>({id:card.id,documentedBy:'md_access_card'}));
export const getExample = id => cards.find(card=>card.id===id || card.slug===id);
export function getScenario(cardId,scenarioId='default') {const card=getExample(cardId);return card?.scenarios.find(scenario=>scenario.id===scenarioId);}
